 ix=next(i for i,p in enumerate(snap['positions']) if p['symbol']==t);snapref=sqlref('broker_observation','id',r['id'],r['body_hash'],'/positions/'+str(ix),r['received_at'])
 mr=next(x for x in man['requests'] if x['apiId']=='5.11' and x['ticker']==t);raw=(root/cap/mr['rawPath']).read_bytes();assert sha(raw)==mr['sha256'];master=json.loads(raw)['content'][0];mi=next(i for i,x in enumerate(members) if x['ticker']==t);assert mr['securityId']==members[mi]['securityId'];hr=[x for x in history if x['symbol']==t];hm=[{'index':i,'isin':x.get('isin'),'name':x.get('name'),'securitiesType':x.get('securitiesType'),'matchesProviderIsin':x.get('isin')==master['isinCode'],'evidence':{'reference':reference,'sha256':file(reference),'pointer':'/data/list/'+str(i),'knownAt':'UNKNOWN','limitation':'retained historical capture; retrieval receipt must be qualified separately'}} for i,x in enumerate(hsx) if x['code']==t]
 dossier={'recordType':'INCOMPLETE_IDENTITY_EVIDENCE_DOSSIER_NOT_BRIDGE_ROW','ledgerSecurityId':t,'ledgerNamespace':'data/vn30.sqlite/security.id','ledgerNamespaceAuthority':'LOCAL_SCHEMA_ONLY_NOT_ACCEPTED_NAMESPACE','portfolioId':projection['portfolioId'],'ledgerQuantity':h['quantity'],'ledgerTransactions':txs,'openingSnapshot':{'evidence':snapref,'holdingsAsOf':snap.get('holdingsAsOf'),'stableIdentifiersPresent':False,'fields':list(snap['positions'][ix])},'market':{'marketUUID':mr['securityId'],'marketNamespace':'PINNED_LEVEL1_RELEASE_MEMBERS','provider':'TCBS','providerInstrumentCode':master['codeId'],'isin':master['isinCode'],'ticker':master['symbol'],'exchange':'HOSE','securityClass':'COMMON_SHARE','providerVenueCode':master['tradePlace'],'providerClassCode':master['secType'],'status':master['status'],'halt':master['halt'],'masterEvidence':{'reference':cap+'/'+mr['rawPath'],'sha256':mr['sha256'],'pointer':'/content/0','knownAt':mr['retrievedAt']},'uuidAssignmentEvidence':{'reference':release,'sha256':file(release),'pointer':'/partition/members/'+str(mi),'knownAt':'UNKNOWN','limitation':'local immutable namespace assignment, not a TCBS UUID or ledger-continuity witness'}},'historicalTCBSIdentities':hr,'historicalIdentitySameProviderConsistent':bool(hr) and all(x['codeId']==master['codeId'] and x['isin']==master['isinCode'] and x['venueCode']==master['tradePlace'] and x['classCode']==master['secType'] for x in hr),'historicalHOSECorroboration':hm,'relationship':'UNKNOWN','validFrom':'UNKNOWN','validTo':'UNKNOWN','knownFrom':'UNKNOWN','knownTo':'UNKNOWN','recordedAt':'UNKNOWN','corporateActionStatus':'UNKNOWN','corporateActionEvidence':'UNKNOWN','continuityEvidence':'UNKNOWN','intervalEvidence':'UNKNOWN','missingEvidence':unknown,'bridgeCandidateCreated':False,'acceptedMapping':False,'eligibility':'INSUFFICIENT_EVIDENCE'}
 dossiers.append(dossier)
