rawhistory=[]
for mp in sorted((root/'data/market-source/tcbs').glob('*/manifest.json')):
 try:m=json.loads(mp.read_text())
 except Exception:continue
 for q in m.get('requests',[]):
  if q.get('apiId')!='5.11' or q.get('ticker') not in {h['securityId'] for h in held} or not q.get('rawPath'):continue
